head.script:
var odoo = {
  csrf_token: "",
  debug: "",
};
odoo.__session_info__ = ;
if (!/(^|;\s)tz=/.test(document.cookie)) {
  const userTZ = Intl.DateTimeFormat().resolvedOptions().timeZone;
  document.cookie = `tz=${userTZ}; path=/`;
}

t.script:
function getCookie(name) {
  const value = `; ${document.cookie}`;
  const parts = value.split(`; ${name}=`);
  if (parts.length === 2) {
    return parts.pop().split(";").shift();
  }
  return null;
}
const color_scheme = getCookie('color_scheme');
var config = ;
config.editorConfig.customization.uiTheme = color_scheme ? `default-${color_scheme}` : "default-light";
if (window?.opener?.location?.href) {
  if (window.opener.location.origin === window.origin) {
    config.editorConfig.customization.goback = {
      blank: false,
      url: window.opener.location.href
    }
  }
}

// Pass document data to global scope for init script
window.odooDocumentId = ;
window.odooJwtToken = "";
window.odooFilterValues = ;
window.hasOdooFormulas = ;

// Setup ODOO custom functions event handler BEFORE creating editor
config.events = config.events || {};
var originalOnReady = config.events.onDocumentReady;
config.events.onDocumentReady = function() {
  if (originalOnReady) {
    originalOnReady();
  }
  // Call init function from external script
  if (window.initializeOdooCustomFunctions && window.hasOdooFormulas) {
    window.initializeOdooCustomFunctions();
  }
};
if (window.DocsAPI) {
  window.docEditor = new DocsAPI.DocEditor("doceditor", config);
} else {
  document.getElementById("error").classList.remove("d-none");
}
